-- Mobile project configuration and the additive Mobile App SDLC template.
alter table public.projects
  add column project_type text not null default 'standard',
  add column platforms text[] not null default '{}',
  add constraint projects_project_type_check check (project_type in ('standard', 'mobile-app')),
  add constraint projects_platforms_check check (
    (project_type = 'standard' and cardinality(platforms) = 0) or
    (project_type = 'mobile-app' and cardinality(platforms) between 1 and 3
      and platforms <@ array['ios', 'android', 'web']::text[]
      and array_position(platforms, null) is null
      and cardinality(platforms) = (case when 'ios' = any(platforms) then 1 else 0 end
        + case when 'android' = any(platforms) then 1 else 0 end
        + case when 'web' = any(platforms) then 1 else 0 end))
  );

-- Existing users keep their edited workflows and default selection.
with owners as (select distinct user_id from public.workflows),
missing as (
  select user_id, gen_random_uuid() as id from owners
  where not exists (select 1 from public.workflows w where w.user_id = owners.user_id and w.definition ? 'mobilePlatforms')
)
insert into public.workflows (id, user_id, name, definition, is_default)
select id, user_id, 'Mobile App SDLC', jsonb_set('{"id":"wf-mobile-app","name":"Mobile App SDLC","description":"BDD tests → implementation plan → review both plans → iOS → Android → Web → review → verify BDD → ready for release.","entryStepId":"todo","steps":[{"id":"todo","type":"human","label":"Todo","state":"todo","position":{"x":40,"y":100}},{"id":"planning","type":"agent","label":"Planning Agent","state":"planning","engine":"claude","model":"claude-opus-5","mode":"high","output":"plan","prompt":"You are a senior software engineer and technical lead working on task {{task_key}}: \"{{task_title}}\".\n\nFollow the `investigate-task` and `plan-change` skills if they are available; otherwise follow their contracts directly.\n\n1. Investigate the codebase to understand existing patterns, architecture, tests and constraints before planning.\n2. Define the task contract before planning. Preserve the imported outcome and acceptance criteria when they are already accurate; otherwise generate missing values or revise them to address the user''s feedback. Acceptance criteria must be observable and testable.\n3. Start the plan with concise sections named exactly `What behavior is changing`, `What files/systems are affected`, `Important invariants`, `Edge cases`, and `How correctness will be verified`. Include the structured task contract in those sections: the behavior section must reflect the outcome, and the verification section must cover every acceptance criterion. Then provide a precise, actionable implementation plan with numbered steps, files expected to change, risk controls, and a verification contract.\n4. Optimize for one coherent implementation per ticket. Do not split the task into subtasks for reviewability alone; a later review-slicing step will arrange the final branch into ordered, human-reviewable commits and explain each one.\n\nTask description:\n{{task_description}}\n\nImported/current outcome (generate one if empty; revise it when the user''s feedback asks you to):\n{{task_outcome}}\n\nImported/current acceptance criteria (generate them if empty; revise them when the user''s feedback asks you to):\n{{acceptance_criteria}}\n\nPrevious plan (empty if this is the first pass):\n{{plan}}\n\nUser feedback to address (empty if none):\n{{feedback}}\n\n\n\n## Mobile engineering contract\nSelected platforms, in implementation order: {{mobile_platforms}}\nUse one monorepo with top-level ios/, android/, web/ folders; create the selected platform apps and keep unselected apps out of scope. Keep shared backend migrations and configuration in supabase/ for one standard Supabase project used by all clients. Never place service-role credentials in clients.\niOS must use SwiftUI. Android must use Kotlin and Jetpack Compose with layered architecture, repositories, ViewModels, unidirectional data flow, coroutines and Flow; consult https://developer.android.com/topic/architecture/recommendations for current guidance. Web must use React.\nImplement selected platforms in order: iOS, then Android, then Web. Use the completed iOS implementation as the behavioral and API reference for Android, preserving idiomatic platform UX. If iOS is unselected, start with the first selected platform. Keep behavior and Supabase contracts consistent across clients.\n\nBDD plan (mandatory behavior contract; do not silently weaken scenarios):\n{{bdd_plan}}\n\nPrior platform handoff summaries (reference the committed source as well):\n{{platform_implementations}}","tools":["read_file","search_codebase","list_directory"],"permissions":["read"],"resumeSessionKey":"planning","position":{"x":400,"y":100}},{"id":"plan-review","type":"human","label":"Plan Review","state":"plan-review","position":{"x":580,"y":100}},{"id":"planning-feedback","type":"agent","label":"Revise Plan","state":"planning-feedback","engine":"claude","model":"claude-opus-5","mode":"high","output":"plan","prompt":"You are a senior software engineer and technical lead working on task {{task_key}}: \"{{task_title}}\".\n\nFollow the `investigate-task` and `plan-change` skills if they are available; otherwise follow their contracts directly.\n\n1. Investigate the codebase to understand existing patterns, architecture, tests and constraints before planning.\n2. Define the task contract before planning. Preserve the imported outcome and acceptance criteria when they are already accurate; otherwise generate missing values or revise them to address the user''s feedback. Acceptance criteria must be observable and testable.\n3. Start the plan with concise sections named exactly `What behavior is changing`, `What files/systems are affected`, `Important invariants`, `Edge cases`, and `How correctness will be verified`. Include the structured task contract in those sections: the behavior section must reflect the outcome, and the verification section must cover every acceptance criterion. Then provide a precise, actionable implementation plan with numbered steps, files expected to change, risk controls, and a verification contract.\n4. Optimize for one coherent implementation per ticket. Do not split the task into subtasks for reviewability alone; a later review-slicing step will arrange the final branch into ordered, human-reviewable commits and explain each one.\n\nTask description:\n{{task_description}}\n\nImported/current outcome (generate one if empty; revise it when the user''s feedback asks you to):\n{{task_outcome}}\n\nImported/current acceptance criteria (generate them if empty; revise them when the user''s feedback asks you to):\n{{acceptance_criteria}}\n\nPrevious plan (empty if this is the first pass):\n{{plan}}\n\nUser feedback to address (empty if none):\n{{feedback}}\n\n\n\n## Mobile engineering contract\nSelected platforms, in implementation order: {{mobile_platforms}}\nUse one monorepo with top-level ios/, android/, web/ folders; create the selected platform apps and keep unselected apps out of scope. Keep shared backend migrations and configuration in supabase/ for one standard Supabase project used by all clients. Never place service-role credentials in clients.\niOS must use SwiftUI. Android must use Kotlin and Jetpack Compose with layered architecture, repositories, ViewModels, unidirectional data flow, coroutines and Flow; consult https://developer.android.com/topic/architecture/recommendations for current guidance. Web must use React.\nImplement selected platforms in order: iOS, then Android, then Web. Use the completed iOS implementation as the behavioral and API reference for Android, preserving idiomatic platform UX. If iOS is unselected, start with the first selected platform. Keep behavior and Supabase contracts consistent across clients.\n\nBDD plan (mandatory behavior contract; do not silently weaken scenarios):\n{{bdd_plan}}\n\nPrior platform handoff summaries (reference the committed source as well):\n{{platform_implementations}}","tools":["read_file","search_codebase","list_directory"],"permissions":["read"],"resumeSessionKey":"planning","position":{"x":400,"y":380}},{"id":"review-slice","type":"agent","label":"Review Slicer","state":"review-slice","engine":"claude","model":"claude-opus-5","mode":"high","output":"review-slice","prompt":"You are a senior engineer preparing task {{task_key}}: \"{{task_title}}\" for human code review.\n\nThe implementation is complete on the current branch. Your job is to make the final PR easy to review as one change by arranging the branch into ordered, logical commits and writing a commit-by-commit review guide.\n\nRules:\n- Preserve the net behavior of the implementation. You may rewrite local commit history, reorder commits, split commits, squash noisy fixups, and improve commit messages, but do not introduce unrelated behavior changes.\n- Each final commit should be a self-contained review unit with a clear title. Prefer a small number of meaningful commits over one giant commit or many mechanical crumbs.\n- Run lightweight validation after rewriting history. If full tests are too expensive, explain the focused checks you ran.\n- Do not push and do not open a PR; the worker publishes the final branch after you return the result.\n\nFor every final commit in order, include the repository, commit sha, title, changed files, a concise explanation, and any focused reviewer notes.\n\nTask description:\n{{task_description}}\n\nRequired outcome:\n{{task_outcome}}\n\nAcceptance criteria:\n{{acceptance_criteria}}\n\nApproved plan:\n{{plan}}\n\nImplementation / reviewer feedback to preserve (may be empty):\n{{feedback}}\n\n## Mobile engineering contract\nSelected platforms, in implementation order: {{mobile_platforms}}\nUse one monorepo with top-level ios/, android/, web/ folders; create the selected platform apps and keep unselected apps out of scope. Keep shared backend migrations and configuration in supabase/ for one standard Supabase project used by all clients. Never place service-role credentials in clients.\niOS must use SwiftUI. Android must use Kotlin and Jetpack Compose with layered architecture, repositories, ViewModels, unidirectional data flow, coroutines and Flow; consult https://developer.android.com/topic/architecture/recommendations for current guidance. Web must use React.\nImplement selected platforms in order: iOS, then Android, then Web. Use the completed iOS implementation as the behavioral and API reference for Android, preserving idiomatic platform UX. If iOS is unselected, start with the first selected platform. Keep behavior and Supabase contracts consistent across clients.\n\nBDD plan (mandatory behavior contract; do not silently weaken scenarios):\n{{bdd_plan}}\n\nPrior platform handoff summaries (reference the committed source as well):\n{{platform_implementations}}","tools":["read_file","write_file","run_command","search_codebase","list_directory","create_pr"],"permissions":["read","write","execute"],"position":{"x":1300,"y":100}},{"id":"adversarial-review","type":"agent","label":"Adversarial Review","state":"adversarial-review","engine":"claude","model":"claude-opus-5","mode":"high","output":"review","prompt":"You are an independent reviewer for task {{task_key}}: \"{{task_title}}\". You did not write this change.\n\nFollow the `adversarial-review` skill (https://github.com/thelimeburner/ai-engineering-skills/blob/main/skills/adversarial-review/SKILL.md) if available; otherwise apply its contract directly:\n- Try to prove the implementation wrong across requirements, authorization, input/data, concurrency, reliability, compatibility, security/privacy, performance, operations, tests and maintainability.\n- Do not rubber-stamp because tests pass. Do not edit code.\n- Every finding needs evidence, a concrete failure scenario, the smallest remediation and a regression test.\n- Produce the required output sections (Diff explanation, Review scope, Findings ordered by severity, Non-findings worth noting, Review verdict).\n\nRun these review passes in order:\n\n1. Explain this diff to a senior engineer. For every changed file, explain why it changed, what assumptions were made, and what could be wrong.\n2. Try to break your implementation. Look for race conditions, incorrect assumptions, missing validation, authorization problems, bad error handling, backwards compatibility issues, and untested edge cases.\n\nReview the diff of the current branch against its base branch. Pull request: {{pr_url}}\n\nTask description:\n{{task_description}}\n\nRequired outcome:\n{{task_outcome}}\n\nAcceptance criteria to review against:\n{{acceptance_criteria}}\n\nApproved plan:\n{{plan}}\n\nReview slice guide:\n{{review_slices}}\n\n## Mobile engineering contract\nSelected platforms, in implementation order: {{mobile_platforms}}\nUse one monorepo with top-level ios/, android/, web/ folders; create the selected platform apps and keep unselected apps out of scope. Keep shared backend migrations and configuration in supabase/ for one standard Supabase project used by all clients. Never place service-role credentials in clients.\niOS must use SwiftUI. Android must use Kotlin and Jetpack Compose with layered architecture, repositories, ViewModels, unidirectional data flow, coroutines and Flow; consult https://developer.android.com/topic/architecture/recommendations for current guidance. Web must use React.\nImplement selected platforms in order: iOS, then Android, then Web. Use the completed iOS implementation as the behavioral and API reference for Android, preserving idiomatic platform UX. If iOS is unselected, start with the first selected platform. Keep behavior and Supabase contracts consistent across clients.\n\nBDD plan (mandatory behavior contract; do not silently weaken scenarios):\n{{bdd_plan}}\n\nPrior platform handoff summaries (reference the committed source as well):\n{{platform_implementations}}","tools":["read_file","search_codebase","list_directory","run_command"],"permissions":["read","execute"],"position":{"x":1480,"y":100}},{"id":"verify","type":"agent","label":"Verify & Readiness","state":"verify","engine":"claude","model":"claude-opus-5","mode":"high","output":"verdict","prompt":"You are the final technical gate for task {{task_key}}: \"{{task_title}}\".\n\nFollow the `verify-change` and `production-readiness` skills if available; otherwise apply their contracts directly:\n1. Run the repository''s real compiler, typechecker, linters and tests. Never claim a check passed unless you executed it.\n2. Check that the change achieves the required outcome and evaluate every acceptance criterion with concrete evidence. Also check that it follows best practice and stays within scope.\n3. Evaluate every production-readiness gate and produce the readiness matrix, residual risks, rollout recommendation and human attention points.\n4. Return GO only when verification is VERIFIED and there are no unresolved material findings from the adversarial review below. Otherwise return NO_GO with precise, actionable feedback for the implementer.\n5. The adversarial review has its own verdict vocabulary (MATERIAL_FINDINGS, NO_MATERIAL_FINDINGS, REVIEW_BLOCKED). Use it only as evidence in your report. Your final JSON verdict must be exactly GO or NO_GO.\n\nPull request: {{pr_url}}\n\nTask description:\n{{task_description}}\n\nRequired outcome:\n{{task_outcome}}\n\nAcceptance criteria (the report must account for every item):\n{{acceptance_criteria}}\n\nApproved plan:\n{{plan}}\n\nAdversarial review report:\n{{review}}\n\n## Mobile engineering contract\nSelected platforms, in implementation order: {{mobile_platforms}}\nUse one monorepo with top-level ios/, android/, web/ folders; create the selected platform apps and keep unselected apps out of scope. Keep shared backend migrations and configuration in supabase/ for one standard Supabase project used by all clients. Never place service-role credentials in clients.\niOS must use SwiftUI. Android must use Kotlin and Jetpack Compose with layered architecture, repositories, ViewModels, unidirectional data flow, coroutines and Flow; consult https://developer.android.com/topic/architecture/recommendations for current guidance. Web must use React.\nImplement selected platforms in order: iOS, then Android, then Web. Use the completed iOS implementation as the behavioral and API reference for Android, preserving idiomatic platform UX. If iOS is unselected, start with the first selected platform. Keep behavior and Supabase contracts consistent across clients.\n\nBDD plan (mandatory behavior contract; do not silently weaken scenarios):\n{{bdd_plan}}\n\nPrior platform handoff summaries (reference the committed source as well):\n{{platform_implementations}}\n\nRun ALL approved BDD scenarios on EVERY selected platform against the final branch. Return bddChecks with one entry per scenarioId/platform containing the exact command, status (passed/failed/blocked), and observed evidence. GO requires every scenario/platform check to pass. Missing tests, skipped tests, unavailable simulators/emulators, or missing credentials are NO_GO. Never claim readiness without executing the tests.","tools":["read_file","search_codebase","list_directory","run_command"],"permissions":["read","execute"],"position":{"x":1660,"y":100}},{"id":"in-review","type":"human","label":"Ready for Release","state":"in-review","position":{"x":1840,"y":100}},{"id":"merge","type":"agent","label":"Merge Pull Requests","state":"merge","output":"merge","position":{"x":2020,"y":100}},{"id":"done","type":"end","label":"Done","state":"done","position":{"x":2200,"y":100}},{"id":"bdd","type":"agent","label":"Behavior Driven Design","state":"bdd","engine":"claude","model":"claude-opus-5","mode":"high","output":"bdd-plan","prompt":"Create or revise the Behavior Driven Design plan for {{task_key}}: {{task_title}}.\nInvestigate the existing code before designing tests. Define stable scenario IDs with explicit Given/When/Then, including happy paths, errors, authorization, loading, offline and edge cases relevant to the feature. Every scenario applies to every selected platform. Generate complete Gherkin .feature file contents and concrete native test cases/step definitions in the BDD plan, with executable test files, fixtures, commands, and expected assertions for each selected platform (XCTest/Swift Testing and UI tests for iOS, Kotlin/Compose tests for Android, React tests for Web) and Supabase integration tests where relevant. The implementation planner and implementers must follow these tests. This step generates reviewable test source in the plan without modifying repository files; implementation agents materialize those generated tests in each platform''s test suite. Return both the full readable BDD plan and structured scenarios. Preserve scenario IDs when revising existing behavior.\n\nTask description:\n{{task_description}}\nOutcome:\n{{task_outcome}}\nAcceptance criteria:\n{{acceptance_criteria}}\nCurrent implementation plan:\n{{plan}}\nFeedback:\n{{feedback}}\n\n## Mobile engineering 